#!/usr/bin/env bash
# Submit the FULL job (execution step included) for code generated by the
# mainframe-application skill, to a live Hercules FTP/JES interface.
#
# This writes real rows to DB2 tables and real records to VSAM clusters on
# whatever MF_HOST points at. It must NEVER be invoked without the caller
# (Claude Code) having just asked the user, in this turn, to confirm this
# specific run against this specific instance - the --confirm-execute flag
# below is a second, mechanical gate, not a substitute for that conversation.
#
# Scope: only for jobs/PROCs this skill generated (<JOBNAME>.jcl.txt /
# <PROCNAME>.prc.txt). Do not point this at pre-existing/legacy code.
#
# Required env vars: MF_HOST, MF_TSO_USER, MF_TSO_PASS, MF_HLQ
# Optional env vars:  MF_FTP_PORT (21), MF_POLL_INTERVAL_SECS (10),
#                      MF_POLL_TIMEOUT_SECS (300)
#
# Usage: run_execute.sh --confirm-execute <local-jcl-or-proc-file> <member-name>

set -euo pipefail

CONFIRM=0
ARGS=()
for a in "$@"; do
    if [[ "$a" == "--confirm-execute" ]]; then
        CONFIRM=1
    else
        ARGS+=("$a")
    fi
done

if [[ "$CONFIRM" -ne 1 ]]; then
    echo "ERROR: refusing to submit an execution step without --confirm-execute." >&2
    echo "The user must be asked to confirm this specific run, this turn, before this flag is passed." >&2
    exit 1
fi

LOCAL_FILE="${ARGS[0]:?usage: $0 --confirm-execute <local-jcl-or-proc-file> <member-name>}"
MEMBER_NAME="${ARGS[1]:?usage: $0 --confirm-execute <local-jcl-or-proc-file> <member-name>}"

: "${MF_HOST:?MF_HOST not set - reachable Hercules FTP host required}"
: "${MF_TSO_USER:?MF_TSO_USER not set}"
: "${MF_TSO_PASS:?MF_TSO_PASS not set}"
: "${MF_HLQ:?MF_HLQ not set}"
MF_FTP_PORT="${MF_FTP_PORT:-21}"
MF_POLL_INTERVAL_SECS="${MF_POLL_INTERVAL_SECS:-10}"
MF_POLL_TIMEOUT_SECS="${MF_POLL_TIMEOUT_SECS:-300}"

if [[ ! -f "$LOCAL_FILE" ]]; then
    echo "ERROR: $LOCAL_FILE not found" >&2
    exit 1
fi

echo "About to submit FULL job (execution step included): $MEMBER_NAME against $MF_HOST"
echo "This will write to real DB2/VSAM data on that instance."

WORKDIR="$(mktemp -d)"
trap 'rm -rf "$WORKDIR"' EXIT
FTP_URL="ftp://${MF_HOST}:${MF_FTP_PORT}/"

# --- submit via the FTP-to-JES interface, capture the assigned job number ---
submit_trace="$WORKDIR/submit.trace"
curl -s -v \
    --user "${MF_TSO_USER}:${MF_TSO_PASS}" \
    -Q "SITE FILETYPE=JES" \
    -T "$LOCAL_FILE" \
    "${FTP_URL}${MEMBER_NAME}" \
    >"$WORKDIR/submit.out" 2>"$submit_trace" || {
        echo "ERROR: submit failed - does this FTP server expose SITE FILETYPE=JES?" >&2
        cat "$submit_trace" >&2
        exit 1
    }

JOB_ID="$(grep -oE 'JOB[0-9]+' "$submit_trace" | head -1 || true)"
if [[ -z "$JOB_ID" ]]; then
    echo "ERROR: could not find a job number in the FTP response" >&2
    cat "$submit_trace" >&2
    exit 1
fi
echo "Submitted as $JOB_ID"

# --- poll until the job reaches OUTPUT status or the timeout elapses ---
elapsed=0
in_output=0
while (( elapsed < MF_POLL_TIMEOUT_SECS )); do
    list_out="$WORKDIR/list.out"
    curl -s \
        --user "${MF_TSO_USER}:${MF_TSO_PASS}" \
        -Q "SITE FILETYPE=JES" \
        -Q "SITE JESJOBNAME=${MEMBER_NAME} JESOWNER=${MF_TSO_USER} JESSTATUS=OUTPUT" \
        "$FTP_URL" >"$list_out" 2>/dev/null || true
    if grep -q "$JOB_ID" "$list_out" 2>/dev/null; then
        in_output=1
        break
    fi
    sleep "$MF_POLL_INTERVAL_SECS"
    elapsed=$(( elapsed + MF_POLL_INTERVAL_SECS ))
done

if [[ "$in_output" -ne 1 ]]; then
    echo "ERROR: $JOB_ID did not reach OUTPUT status within ${MF_POLL_TIMEOUT_SECS}s" >&2
    exit 1
fi

# --- retrieve the job log ---
joblog="$WORKDIR/${JOB_ID}.log"
curl -s \
    --user "${MF_TSO_USER}:${MF_TSO_PASS}" \
    -Q "SITE FILETYPE=JES" \
    "${FTP_URL}${JOB_ID}.x" -o "$joblog" || {
        echo "ERROR: could not retrieve job log for $JOB_ID" >&2
        exit 1
    }

# --- parse per-step condition codes and any SQLCODE, report, exit non-zero on failure ---
echo ""
echo "Run result for $MEMBER_NAME ($JOB_ID):"
echo "-------------------------------------------------------------"
overall_rc=0
grep -E 'COND CODE|SQLCODE' "$joblog" | sed 's/^/  /'

max_cc="$(grep -oE 'COND CODE[[:space:]]+[0-9]+' "$joblog" | grep -oE '[0-9]+' | sort -n | tail -1 || echo 0)"
bad_sql="$(grep -E 'SQLCODE' "$joblog" | grep -vE 'SQLCODE *=? *0+([^0-9]|$)' || true)"

echo "-------------------------------------------------------------"
if [[ -n "$bad_sql" ]]; then
    echo "FAIL: non-zero SQLCODE found"
    overall_rc=1
elif [[ -n "$max_cc" && "$max_cc" -gt 4 ]]; then
    echo "FAIL: highest condition code was $max_cc"
    overall_rc=1
elif [[ -n "$max_cc" && "$max_cc" -eq 4 ]]; then
    echo "WARN: highest condition code was 4 - review warnings above"
else
    echo "PASS: job completed clean, RC=0"
fi
echo "Full job log saved at: $joblog (not copied elsewhere - review before sharing)"
echo "Next: verify actual output per the Hercules run book (steps 10-11) - RC alone doesn't confirm the business result."

exit "$overall_rc"
